cd /app && cat > app/mailers/application_mailer.rb <<'EOF'
class ApplicationMailer < ActionMailer::Base
  # A proc, so HELPDESK_MAIL_FROM is read when mail is sent, not at boot.
  default from: proc { Helpdesk::Settings.mail_from }
  layout "mailer"

  # Sends a mail and logs failures instead of raising. A failed send must not
  # undo a committed signup or a freshly issued token; the user can ask for
  # another link.
  def self.deliver_safely(mail_name, *args)
    public_send(mail_name, *args).deliver_now
  rescue StandardError => e
    Rails.logger.error("[helpdesk] #{mail_name} email failed: #{e.class}: #{e.message}")
    nil
  end
end
EOF
cat > app/mailers/user_mailer.rb <<'EOF'
class UserMailer < ApplicationMailer
  def email_verification(user, token)
    @user = user
    @account = user.account
    @link = Helpdesk::Settings.frontend_link("/verify-email", account: @account.subdomain, token: token)
    @valid_for = EmailVerification::TTL.inspect

    mail to: user.email, subject: "Verify your email for #{@account.name}"
  end

  # Sent when mail to a business's support address opens a request for someone who has no account there yet.
  # The account gets a random password nobody knows, so the person sets their own with the password reset
  # before they can sign in to the portal.
  def support_verification(user, token)
    @user = user
    @account = user.account
    @link = Helpdesk::Settings.frontend_link("/verify-email", account: @account.subdomain, token: token)
    @valid_for = EmailVerification::TTL.inspect

    mail to: user.email, subject: "Verify your email for #{@account.name} support"
  end

  # Invites someone to join the business as an admin or agent. The link opens the frontend's acceptance screen.
  def invitation(invitation, token)
    @invitation = invitation
    @account = invitation.account
    @role = invitation.role
    @link = Helpdesk::Settings.frontend_link("/accept-invitation", account: @account.subdomain, token: token)
    @valid_for = Invitation::TTL.inspect

    mail to: invitation.email, subject: "You're invited to join #{@account.name} on Helpdesk"
  end

  def password_reset(user, token)
    @user = user
    @account = user.account
    @link = Helpdesk::Settings.frontend_link("/reset-password", account: @account.subdomain, token: token)
    @valid_for = PasswordReset::TTL.inspect

    mail to: user.email, subject: "Reset your password for #{@account.name}"
  end
end
EOF
cat > app/mailers/ticket_mailer.rb <<'EOF'
class TicketMailer < ApplicationMailer
  # A public staff reply on a request that came in by email. It goes to the requester from the business's support
  # address. Replies to it go to the request's private reply address, so they come back to this conversation.
  def staff_reply(comment)
    @comment = comment
    @ticket = comment.ticket
    @account = @ticket.account
    @requester = @ticket.requester

    # Thread the reply under the requester's emails, so mail clients show one conversation.
    message_ids = @ticket.comments.where.not(inbound_message_id: nil).pluck(:inbound_message_id)
    if message_ids.any?
      headers["In-Reply-To"] = "<#{message_ids.last}>"
      headers["References"] = message_ids.map { |id| "<#{id}>" }.join(" ")
    end

    subject = @ticket.subject.match?(/\Are:/i) ? @ticket.subject : "Re: #{@ticket.subject}"
    mail to: @requester.email,
         from: "#{@account.name} Support <#{@account.support_address}>",
         reply_to: "#{@account.name} Support <#{@ticket.reply_address}>",
         subject: subject
  end
end
EOF
mkdir -p app/views/ticket_mailer && cat > app/views/user_mailer/support_verification.text.erb <<'EOF'
Hi <%= @user.name %>,

We received your email to <%= @account.name %> support and opened a request for you. To follow your requests and reply in the portal, verify your email address by opening this link:

<%= @link %>

The link is valid for <%= @valid_for %>. To sign in, use the password reset option with this email address to choose a password. If you did not write to <%= @account.name %> support, you can ignore this email.
EOF
cat > app/views/ticket_mailer/staff_reply.text.erb <<'EOF'
Hi <%= @requester.name %>,

<%= @comment.body %>

---
Reply to this email to add to your request "<%= @ticket.subject %>". Your reply goes straight into that conversation.
EOF
